mapper.select:
SELECT id, tenant_id, template_name, language, category, status,
       rejection_reason, components, preview_url, last_sync_time,
       create_time, update_time
FROM crm_whatsapp_template
WHERE tenant_id = #{tenantId}

    AND LOWER(status) = LOWER(#{status})


    AND category = #{category}


    AND language = #{language}


    AND template_name ILIKE '%' || #{keyword} || '%'

ORDER BY update_time DESC NULLS LAST

SELECT id, tenant_id, template_name, language, category, status,
       rejection_reason, components, preview_url, last_sync_time,
       create_time, update_time
FROM crm_whatsapp_template
WHERE tenant_id = #{tenantId}
  AND template_name = #{templateName}
  AND language = #{language}
LIMIT 1

mapper.update:
UPDATE crm_whatsapp_template
SET last_sync_time = #{lastSyncTime}, update_time = now()
WHERE id = #{id}
